    expect(yaml).toContain('interval: "15m"');
    expect(yaml).toContain('max_tick: "2m"');
    expect(yaml).not.toContain('interval: "1h"');
    expect(yaml).not.toContain('max_tick: "10m"');
    rmSync(home, { recursive: true, force: true });
