function writeFakeGit(bin: string, fixtureRepo: string): void {
  writeFileSync(
    join(bin, "git"),
    `#!/bin/sh
if [ "$1" = clone ]; then
  dest=""
  for a in "$@"; do dest="$a"; done
  mkdir -p "$dest"
  cp -R "${fixtureRepo}/." "$dest/"
  exit 0
fi
exit 0
`,
  );
  chmodSync(join(bin, "git"), 0o755);
}

