const APPLY_ARGS = {
  ...WRITE_ARGS,
  "keep-copies": { type: "boolean" as const, description: "Do not refresh copied skills from origin", default: false },
  from: { type: "string" as const, description: "Backfill origin and refresh skills that have none" },
};

async function runApply(
  slug: string,
  args: {
    yes?: boolean;
    "dry-run"?: boolean;
    format?: string;
    json?: boolean;
    ci?: boolean;
    "keep-copies"?: boolean;
    from?: string;
  },
): Promise<void> {
  if (!hermesInstalled()) {
    printHermesInstall();
    await exit(2);
    return;
  }
  const dryRun = Boolean(args["dry-run"]);
  const yes = Boolean(args.yes);
  if (shouldBlockAgentWrite({ agent: isAgentCaller(), yes, dryRun })) {
    refuseAgentWrite("dora harness apply <slug> --yes");
    await exit(2);
    return;
  }
  const home = homedir();
  const mode = resolveOutputMode(args);
  let routine;
  try {
    routine = readRoutine(home, slug);
  } catch (e) {
    ui.fail(e instanceof Error ? e.message : String(e));
    nextAction("dora harness list");
    await exit(1);
    return;
  }
  if (!dryRun) {
    try {
      const result = refreshRoutineSkills(home, slug, {
        cwd: process.cwd(),
        keepCopies: Boolean(args["keep-copies"]),
        from: typeof args.from === "string" ? args.from.trim() || undefined : undefined,
      });
      if (result.refreshed.length) ui.dim(`  Refreshed ${result.refreshed.join(", ")}.`);
      if (result.localOnly.length) {
        ui.dim(`  Local origin (disk only, not fetched): ${result.localOnly.join(", ")}.`);
      }
    } catch (e) {
      ui.fail(e instanceof Error ? e.message : String(e));
      nextAction("dora harness list");
      await exit(1);
      return;
    }
  }
  const jobs = listCronJobs();
  let action: "create" | "edit" = "create";
  let jobId: string | undefined;
  const live = routine.jobId && jobs?.some((j) => j.id === routine.jobId) ? routine.jobId : undefined;
  const named = jobs?.find((j) => j.name === slug);
  if (live) {
    action = "edit";
    jobId = live;
  } else if (named) {
    action = "edit";
    jobId = named.id;
    if (!dryRun) writeRoutineJobId(home, slug, named.id);
  } else if (routine.jobId && jobs === null) {
    action = "edit";
    jobId = routine.jobId;
  }
  const cmds = action === "edit" && jobId ? [editArgs(routine, jobId)] : bootArgs(routine);
  if (dryRun) {
    for (const c of cmds) ui.info(`  ${formatHermesCmd(c)}`);
    if (mode.format === "json") outJson({ slug, action, dryRun: true });
    nextAction(`dora harness apply ${slug} --yes`);
    ui.blank();
    await exit(0);
    return;
  }
  try {
    const out = runHermesCmds(cmds);
    if (action === "create") {
      const created = parseCreatedJobId(out);
      if (!created) throw new Error("Hermes did not print a job id.");
      writeRoutineJobId(home, slug, created);
      jobId = created;
    }
    if (mode.format === "json") {
      outJson({ slug, action, jobId: jobId ?? null });
      await exit(0);
      return;
    }
    ui.info(`  Applied ${slug}. Dora does not own the timer.`);
    ui.dim("  Laptop close is host sleep, not pause. Due jobs can fire on wake if the job is not paused.");
    if (usesMcp(routine.mcpUrl)) printMcpNext();
    else printWatch();
    nextAction(`dora harness show ${slug}`);
    ui.blank();
    await exit(0);
  } catch (e) {
    ui.fail(e instanceof Error ? e.message : String(e));
    if (usesMcp(routine.mcpUrl)) printMcpNext();
    else printWatch();
    nextAction("dora harness list");
    await exit(1);
  }
}

